var i=`1196-rellenitos-de-platano`;var t=`world-1196`;var a=`GT`;var o=`central-america-caribbean`;var s=8;var r=67;var l={en:`Rellenitos de Plátano`,ua:`Рельєнітос із плантану`};var d={en:`Rellenitos de Plátano is a dish from Guatemala prepared with plantain, canned black beans. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Рельєнітос із плантану, страва кухні країни Гватемала, яку готують із таких продуктів: плантан, консервована чорна квасоля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`plantain`,750,`g`],[`water`,950,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 8 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 8 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:8,i:[[`ground-cinnamon`,4,`g`],[`white-granulated-sugar`,35,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:9,i:[[`canned-black-beans`,280,`g`],[`unsalted-butter`,25,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 14 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 14 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:14,i:[[`canola-oil`,90,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,80,`g`]]}];var h={slug:i,id:t,country:`GT`,region:o,servings:8,minutes:67,title:l,text:d,steps:u};export{a as country,h as default,t as id,r as minutes,o as region,s as servings,i as slug,u as steps,d as text,l as title};